// ============================================
// TRANSFORMATION COMPULOCKS → PRESTASHOP 1.7.4
// Elockstore.com
// ============================================

const items = $input.all();
const results = [];

// --- Traductions EN → FR ---
const TERMS = {
  'Space Enclosure': 'Boîtier Space',
  'Apex Secured Enclosure': 'Boîtier Sécurisé Apex',
  'Enclosure': 'Boîtier',
  'Secured Kickstand': 'Support Chevalet Sécurisé',
  'Kickstand': 'Support Chevalet',
  'Wall Mount': 'Fixation Murale',
  'Floor Stand': 'Totem Sur Pied',
  'Desk Mount': 'Support Bureau',
  'Swing Arm': 'Bras Pivotant',
  'Articulating Arm': 'Bras Articulé',
  'Extra Long Arm': 'Bras Extra Long',
  'Reach Arm': 'Bras Extensible Reach',
  'Cable Lock': 'Câble Antivol',
  'Edge Case': 'Coque Edge',
  'Charging Station': 'Station de Recharge',
  'Charging Dock': 'Dock de Recharge',
  'Rise Stand': 'Support Rise',
  'Cling Mount': 'Support Adhésif Cling',
  'POS Stand': 'Support Point de Vente',
  'Kiosk': 'Borne Interactive',
  'Laptop': 'Ordinateur Portable',
  'Tablet': 'Tablette',
  'Black': 'Noir',
  'White': 'Blanc',
  'Silver': 'Argent',
  'High-grade aluminum': 'Aluminium haute qualité',
  'High -grade aluminum': 'Aluminium haute qualité',
  'Conceals charging cable': 'Dissimule le câble de charge',
  'Quick keyed access': 'Accès rapide par clé',
  'VESA pattern': 'Standard VESA',
  'enclosure keys': 'clés pour boîtier',
  'Metal kickstand': 'Support chevalet en métal',
  'extra functionality': 'fonctionnalité supplémentaire',
  'Lock slot and cable lock': 'Emplacement verrou et câble antivol',
  'Mobile protective': 'Protection mobile',
  'Rubber Edge case': 'Coque Edge en caoutchouc',
  'Landscape orientation only': 'Orientation paysage uniquement',
  'Sleek metal frame': 'Cadre métallique élégant',
  'Cooling fan': 'Ventilateur de refroidissement',
  'Multi-protection Safety System': 'Système de sécurité multi-protection',
  'Multi-protection safety system': 'Système de sécurité multi-protection',
  'USB ports': 'ports USB',
  'Ergonomic Monitor Arm Wall Mount': 'Fixation murale bras moniteur ergonomique',
  'Maximum weight': 'Poids maximum',
};

const COLOR_FR = { 'Black':'Noir','White':'Blanc','Silver':'Argent','Gray':'Gris','Grey':'Gris','Red':'Rouge','Blue':'Bleu','Pink':'Rose','Gold':'Or' };
const MATERIAL_FR = { 'ALUMINUM':'Aluminium','Aluminium':'Aluminium','STEEL':'Acier','Steel':'Acier','Plastic':'Plastique','Metal':'Métal','Rubber':'Caoutchouc' };
const COUNTRY_FR = { 'IL':'Israël','CN':'Chine','US':'États-Unis','TW':'Taïwan','DE':'Allemagne' };

// Category rules
const CAT_RULES = [
  { p: /enclosure|space enclosure/i, c: 'Accueil > Supports et Fixations > Boîtiers Tablettes' },
  { p: /kickstand/i, c: 'Accueil > Supports et Fixations > Supports Bureau' },
  { p: /wall mount|wallmount/i, c: 'Accueil > Supports et Fixations > Fixations Murales' },
  { p: /floor stand|floorstand|kiosk/i, c: 'Accueil > Supports et Fixations > Bornes et Totems' },
  { p: /desk mount|desk stand|rise/i, c: 'Accueil > Supports et Fixations > Supports Bureau' },
  { p: /arm|reach|articulating/i, c: 'Accueil > Supports et Fixations > Bras Articulés' },
  { p: /charging|usb.*port|dock/i, c: 'Accueil > Solutions de Recharge' },
  { p: /cable lock|lock slot|t-bar/i, c: 'Accueil > Câbles et Verrous de Sécurité' },
  { p: /case|edge case|rugged/i, c: 'Accueil > Coques et Protections' },
  { p: /cling|grip|holder/i, c: 'Accueil > Supports et Fixations > Supports Universels' },
  { p: /ledge|macbook|laptop/i, c: 'Accueil > Sécurité Laptop' },
  { p: /pos|payment|terminal/i, c: 'Accueil > Solutions Point de Vente' },
  { p: /medical|hospital|patient/i, c: 'Accueil > Solutions Médicales' },
];

// --- Helper functions ---
function fixUPC(val) {
  if (!val) return '';
  let v = val.toString().replace(',', '.');
  try {
    let num = parseFloat(v);
    let result = Math.round(num).toString();
    while (result.length < 12) result = '0' + result;
    return result;
  } catch(e) {
    return val.toString().replace(/[^\d]/g, '');
  }
}

function lbsToKg(val) {
  if (!val) return '';
  let v = parseFloat(val.toString().replace(',', '.'));
  return isNaN(v) ? '' : (v * 0.453592).toFixed(3);
}

function parseDims(val) {
  if (!val) return { w: '', h: '', d: '' };
  let parts = val.toString().split(/[xX×\s]+/).filter(p => p);
  let toCm = (p) => {
    let n = parseFloat(p.replace(',', '.'));
    return isNaN(n) ? '' : (n * 2.54).toFixed(2);
  };
  return {
    w: parts[0] ? toCm(parts[0]) : '',
    h: parts[1] ? toCm(parts[1]) : '',
    d: parts[2] ? toCm(parts[2]) : ''
  };
}

function translate(text) {
  if (!text) return '';
  let r = text;
  // Sort by length desc to match longest first
  let sorted = Object.entries(TERMS).sort((a,b) => b[0].length - a[0].length);
  for (let [en, fr] of sorted) {
    r = r.split(en).join(fr);
  }
  return r;
}

function bulletsToHtml(text) {
  if (!text) return '';
  let items = [];
  if (text.includes('\n')) {
    items = text.split('\n').map(l => l.replace(/^[-•*]\s*/, '').trim()).filter(l => l);
  } else if (text.includes(';')) {
    items = text.split(';').map(i => i.trim()).filter(i => i);
  } else if ((text.match(/,/g) || []).length >= 2) {
    items = text.split(',').map(i => i.trim()).filter(i => i);
  } else {
    return '<p>' + translate(text) + '</p>';
  }
  return '<ul>' + items.map(i => '<li>' + translate(i) + '</li>').join('') + '</ul>';
}

function slugify(text) {
  return text.toString().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\w\s-]/g, '').replace(/[\s_]+/g, '-')
    .replace(/^-+|-+$/g, '').substring(0, 128);
}

function categorize(name) {
  for (let rule of CAT_RULES) {
    if (rule.p.test(name)) return rule.c;
  }
  return 'Accueil > Supports et Fixations';
}

function buildFeatures(d) {
  let f = [];
  let color = (d['Color'] || '').trim();
  if (color) f.push('Couleur:' + (COLOR_FR[color] || color) + ':0:0');
  let mat = (d['Material'] || '').trim();
  if (mat) f.push('Matériau:' + (MATERIAL_FR[mat] || mat) + ':1:0');
  let coo = (d['COO'] || '').trim();
  if (coo) f.push("Pays d'origine:" + (COUNTRY_FR[coo] || coo) + ':2:0');
  let hs = (d['HS Code'] || '').trim();
  if (hs) f.push('Code douanier:' + hs + ':3:0');
  let compat = (d['Compatibility'] || '').trim();
  if (compat) f.push('Compatibilité:' + compat.replace(/\n/g, ' | ') + ':4:0');
  return f.join(',');
}

function buildImages(d) {
  let urls = [];
  for (let k of ['Picture 1','Picture 2','Picture 3','Picture 4']) {
    let url = (d[k] || '').trim();
    if (url) urls.push(url);
  }
  return urls.join(',');
}

// --- Main loop ---
for (const item of items) {
  const d = item.json;
  const pn = (d['PN'] || '').trim();
  const name = (d['Marketing Name'] || '').trim();
  if (!pn || !name) continue;

  const nameFr = translate(name);
  const upc = fixUPC(d['UPC']);
  const dims = parseDims(d['Dimensions (In)']);
  const imageUrls = buildImages(d);
  const imageCount = imageUrls ? imageUrls.split(',').length : 0;

  const bullets = (d['Marketing Bullet Points'] || '').trim();
  const shortDesc = bulletsToHtml(bullets);
  const shortClean = shortDesc.replace(/<[^>]+>/g, '');

  let longDesc = (d['Long description'] || '').trim();
  if (longDesc) {
    longDesc = translate(longDesc).replace(/\n\n/g, '</p><p>').replace(/\n/g, '<br>');
    longDesc = '<p>' + longDesc + '</p>';
  }

  results.push({
    json: {
      'ID': '',
      'Active (0/1)': '1',
      'Name *': nameFr,
      'Categories (x,y,z...)': categorize(name),
      'Price tax excluded': '',
      'Price tax included': '',
      'Tax rule ID': '1',
      'Wholesale price': '',
      'On sale (0/1)': '0',
      'Discount amount': '',
      'Discount percent': '',
      'Discount from (yyyy-mm-dd)': '',
      'Discount to (yyyy-mm-dd)': '',
      'Reference': pn,
      'Supplier reference': pn,
      'Supplier': 'Compulocks',
      'Manufacturer': 'Compulocks',
      'EAN13': upc.length >= 13 ? upc.substring(0,13) : '',
      'UPC': upc.length === 12 ? upc : '',
      'MPN': '',
      'Ecotax': '',
      'Width': dims.w,
      'Height': dims.h,
      'Depth': dims.d,
      'Weight': lbsToKg(d['Weight (lb)']),
      'Delivery time of in-stock products': 'Livraison sous 3-7 jours ouvrés',
      'Delivery time of out-of-stock products': 'Livraison sous 10-21 jours ouvrés',
      'Quantity': '0',
      'Minimal quantity': '1',
      'Low stock level': '',
      'Send me an email when the quantity is under this level (0/1)': '0',
      'Visibility': 'both',
      'Additional shipping cost': '',
      'Unity': '',
      'Unit price': '',
      'Short description': shortDesc,
      'Description': longDesc || shortDesc,
      'Tags (x,y,z...)': '',
      'Meta title': (nameFr + ' - Elockstore').substring(0, 70),
      'Meta keywords': '',
      'Meta description': (shortClean || 'Achetez ' + nameFr + ' sur Elockstore.com').substring(0, 160),
      'URL rewritten': slugify(nameFr),
      'Text when in stock': 'En stock - Expédition sous 48h',
      'Text when backorder allowed': 'Sur commande - Livraison sous 2-3 semaines',
      'Available for order (0/1)': '1',
      'Product availability date': '',
      'Product creation date': '',
      'Show price (0/1)': '1',
      'Image URLs (x,y,z...)': imageUrls,
      'Image alt texts (x,y,z...)': imageUrls ? Array(imageCount).fill(nameFr).join(',') : '',
      'Delete existing images (0/1)': '0',
      'Feature (Name:Value:Position:Customized)': buildFeatures(d),
      'Available online only (0/1)': '0',
      'Condition': 'new',
      'Customizable (0/1)': '0',
      'Uploadable files (0/1)': '0',
      'Text fields (0/1)': '0',
      'Out of stock action': '',
      'Virtual product (0/1)': '0',
      'File URL': '',
      'Number of allowed downloads': '',
      'Expiration date (yyyy-mm-dd)': '',
      'Number of days': '',
      'ID / Name of shop': '',
      'Advanced Stock Management': '0',
      'Depends on stock': '0',
      'Warehouse': '',
      'Accessories (x,y,z...)': ''
    }
  });
}

return results;

// Contrôle qualité + statistiques
const items = $input.all();
let warnings = [];
let categories = {};

for (const item of items) {
  const d = item.json;
  const ref = d['Reference'];
  const name = d['Name *'];

  // Comptage catégories
  let cat = d['Categories (x,y,z...)'] || 'Non catégorisé';
  categories[cat] = (categories[cat] || 0) + 1;

  // Vérifications
  if (!d['Price tax excluded'] && !d['Price tax included']) {
    warnings.push(`[${ref}] ${name} - SANS PRIX`);
  }
  if (!d['EAN13'] && !d['UPC']) {
    warnings.push(`[${ref}] ${name} - Sans code-barres`);
  }
  if (!d['Image URLs (x,y,z...)']) {
    warnings.push(`[${ref}] ${name} - Sans image`);
  }
  if (!d['Short description']) {
    warnings.push(`[${ref}] ${name} - Sans description courte`);
  }
}

console.log('=== RAPPORT IMPORT COMPULOCKS ===');
console.log(`Produits traités: ${items.length}`);
console.log(`Avertissements: ${warnings.length}`);
console.log('');
console.log('Catégories:');
for (const [cat, count] of Object.entries(categories).sort((a,b) => b[1]-a[1])) {
  console.log(`  ${cat}: ${count}`);
}
if (warnings.length > 0) {
  console.log('');
  console.log('Avertissements:');
  for (const w of warnings.slice(0, 20)) {
    console.log(`  ⚠ ${w}`);
  }
  if (warnings.length > 20) {
    console.log(`  ... et ${warnings.length - 20} autres`);
  }
}

return items;

